const crypto = require('crypto');
const input = $input.first().json;
const body = input.body || input;

const approvalId = 'APR-' + crypto.randomBytes(8).toString('hex');

// Approval types: campaign_launch, budget_increase, deal_discount, data_export
const approvalChains = {
  campaign_launch: ['marketing_manager', 'marketing_director'],
  budget_increase: ['finance_manager', 'cfo'],
  deal_discount: ['sales_manager'],
  data_export: ['compliance_officer', 'cto'],
  large_deal: ['sales_director', 'ceo']
};

const type = body.approval_type || 'campaign_launch';
const chain = approvalChains[type] || ['manager'];

return [{ json: {
  approval_id: approvalId,
  approval_type: type,
  title: body.title || 'Approval Request',
  description: body.description || '',
  requested_by: body.requested_by,
  client_id: body.client_id,
  data: body.data || {},
  approval_chain: chain,
  current_step: 0,
  status: 'pending',
  expires_at: new Date(Date.now() + 72 * 60 * 60 * 1000).toISOString()
}}];

